// 页面组件
   function Home() { return <h1>首页</h1>; }
   function User() { 
     const params = useParams(); // 获取 /user/:id 的id
     return <h1>用户{params.id}</h1>; 
   }

   // 导航组件
   function Nav() {
     const navigate = useNavigate();
     return (
       <div>
         <Link to="/">首页</Link>
         <Link to="/user/123">用户123</Link>
         <button onClick={() => navigate('/')}>返回首页</button>
       </div>
     );
   }

// 路由配置
   function App() {
     return (
       <BrowserRouter>
         <Nav />
         <Routes>
           <Route path="/" element={<Home />} />
           <Route path="/user/:id" element={<User />} />
         </Routes>
       </BrowserRouter>
     );
   }
   ```
4. **核心特点**：
   - 基于组件化设计，路由即组件；
   - 支持嵌套路由、路由守卫（控制访问权限）、路由传参；

React组件
### React 组件（极简版）
React 组件是**拆分 UI 的独立可复用单元**，核心就 3 点：

#### 1. 两种形式（函数组件为主）
```jsx
// 函数组件（主流）：返回 UI 结构（JSX）
function Button() {
  return <button>点击</button>;
}

// 类组件（传统）：继承 Component，render 返 UI
// class Button extends React.Component {
//   render() { return <button>点击</button>; }
// }
```

#### 2. 两个核心数据
- **Props**：父组件传给子组件的“参数”，只读（比如给按钮传文字）：
  ```jsx
  function Button(props) {
    return <button>{props.text}</button>;
  }
  // 使用：<Button text="提交" />
  ```
- **State**：组件内部的“可变数据”（比如按钮点击计数）：
  ```jsx
  function Counter() {
    const [count, setCount] = React.useState(0);
    return <button onClick={() => setCount(count+1)}>{count}</button>;
  }
  ```

#### 3. 核心特点

- 单向流：数据只从父到子，Props 不能改；
- 重渲染：Props/State 变了，组件自动更 UI。

Javascript闭包
### JavaScript 闭包（Closure）详解
闭包是 JavaScript 中核心且强大的特性，理解闭包是掌握 JS 作用域、执行上下文和内存管理的关键。本文从**定义、原理、用途、陷阱**四个维度全面解析闭包。

---

## 一、闭包的定义
**闭包**：指一个函数能够访问并保留其**词法作用域**（定义时的作用域）中的变量，即使该函数在其词法作用域之外执行。
简单来说：**函数 + 函数能访问的词法环境 = 闭包**。

### 最小示例
```javascript
function outer() {
  const a = 10; // 外层函数的局部变量
  // 内层函数（闭包）
  function inner() {
    console.log(a); // 访问外层作用域的变量
  }
  return inner; // 返回内层函数，使其能在外部执行
}

const fn = outer(); 
fn(); // 输出 10（即使 outer 已执行完毕，inner 仍能访问 a）
```

